import json, pathlib
p=pathlib.Path(__file__).parent.parent
s=p.name
cases=[
('health','Help me prepare a concise question for my clinician about the symptoms and their timing.', 'My cousin, Elian Moss, came with me to the appointment. I have felt dizzy after breakfast on three mornings this week, but I have not fainted. The feeling usually passes within ten minutes. I started a new exercise routine two weeks ago, although I do not know whether it is related. I would like to ask what information I should track before my next visit.', [('Elian Moss','PERSON','ALIAS','unnecessary'),('I have felt dizzy after breakfast on three mornings this week, but I have not fainted.','HEALTH','KEEP','essential')], ['My cousin,','came with me to the appointment.','I have felt dizzy after breakfast on three mornings this week, but I have not fainted.','The feeling usually passes within ten minutes.','I started a new exercise routine two weeks ago, although I do not know whether it is related.']),
('budget','Help me compare the two monthly expenses and identify their difference.', 'I am revisiting my household budget after a change in my commute. My rent is 720 euros per month and my transit pass costs 58 euros per month. The transit amount does not include occasional taxi trips, which vary too much to estimate here. I want a simple comparison that retains the monthly units and does not assume the two figures are my complete budget.', [('My rent is 720 euros per month','FINANCIAL','KEEP','essential')], ['My rent is 720 euros per month and my transit pass costs 58 euros per month.','The transit amount does not include occasional taxi trips, which vary too much to estimate here.']),
('returns','Draft a polite message asking the shop about the return deadline.', 'I bought a kettle online and the lid does not close properly. The shop says returns are possible within 30 days, but I cannot tell whether that period starts on dispatch or delivery. Please ask which date they use and whether the original box is required. I have not used the kettle and would prefer an exchange if one is available.', [], ['The shop says returns are possible within 30 days, but I cannot tell whether that period starts on dispatch or delivery.','I have not used the kettle and would prefer an exchange if one is available.']),
('event','Organise these notes into a short checklist for a picnic.', 'We are planning a picnic for Saturday afternoon if the rain stops. Bring a blanket, reusable cups and a bag for rubbish. One guest cannot eat peanuts, so check the ingredient labels before packing snacks. There is a public water tap near the entrance. We should choose a meeting point only after checking whether the park gate is open.', [], ['We are planning a picnic for Saturday afternoon if the rain stops.','One guest cannot eat peanuts, so check the ingredient labels before packing snacks.','We should choose a meeting point only after checking whether the park gate is open.']),
('email','Help me write a brief account support request without exposing contact details.', 'Hello support team, my email is sora.marden@example.com. I cannot sign in after changing phones and the recovery screen keeps returning to the beginning. I have already tried a different browser, but I have not reset the account. Could you explain what recovery options are available and whether my saved preferences will remain intact? Please keep the tone courteous and concise.', [('sora.marden@example.com','EMAIL','PLACEHOLDER','unnecessary')], ['I cannot sign in after changing phones and the recovery screen keeps returning to the beginning.','I have already tried a different browser, but I have not reset the account.','Could you explain what recovery options are available and whether my saved preferences will remain intact?']),
('housing','Help me organise this note.', 'My neighbour, Ivo Rell, mentioned that the shared hallway light flickers in the evening. It has not gone out completely, but the switch sometimes clicks twice. I wrote down that the building manager should check it before anyone replaces the bulb. I am unsure whether the same problem occurs in daylight, so please retain that uncertainty when arranging the note.', [('Ivo Rell','PERSON','ALIAS','unnecessary')], ['It has not gone out completely, but the switch sometimes clicks twice.','I am unsure whether the same problem occurs in daylight, so please retain that uncertainty when arranging the note.']),
('study','Make a study plan based on these constraints.', 'I have four chapters to review before the exam. I can study for 45 minutes on Monday and Wednesday, but only 20 minutes on Friday. I find diagrams more useful than rereading and want a short practice quiz after each chapter. The exam date has not been confirmed, so do not assume a deadline. Leave time to revisit difficult material.', [], ['I can study for 45 minutes on Monday and Wednesday, but only 20 minutes on Friday.','I find diagrams more useful than rereading and want a short practice quiz after each chapter.','The exam date has not been confirmed, so do not assume a deadline.']),
('procure','Draft a generic supplier follow-up for external AI, omitting confidential identities and pricing.', 'Our buyer, Nella Quist, spoke to confidential supplier Reedvale Components about the delayed sample shipment. The supplier said the revised packing list is ready, but the collection time has not been confirmed. Ask for the collection window and the name of a shipping contact without promising a delivery date. The unapproved internal quote is 42,600 euros and must remain confidential.', [('Nella Quist','PERSON','ALIAS','unnecessary'),('Reedvale Components','ORG','PLACEHOLDER','unnecessary'),('42,600 euros','FINANCIAL','PLACEHOLDER','unnecessary')], ['Our buyer,','spoke to confidential supplier','about the delayed sample shipment.','The supplier said the revised packing list is ready, but the collection time has not been confirmed.','Ask for the collection window and the name of a shipping contact without promising a delivery date.']),
('credential','Explain the troubleshooting steps without exposing the credential.', 'An engineer wrote: my password is violet-harbor-73. The staging service returned a timeout after the certificate was renewed. A second attempt from the same machine also timed out, while the status page reported no outage. Suggest a short sequence of checks that does not require sharing the password. We have not established whether the certificate change caused the failure.', [('violet-harbor-73','SECRET','PLACEHOLDER','unnecessary')], ['The staging service returned a timeout after the certificate was renewed.','A second attempt from the same machine also timed out, while the status page reported no outage.','We have not established whether the certificate change caused the failure.']),
('finance','Summarise the budget variance for an external assistant without disclosing the confidential amount.', 'Our internal finance note says the confidential projected shortfall is 18,750 euros for the quarter. The estimate assumes the planned shipment arrives in March; it does not include a possible refund. Please outline what additional information we need before discussing the variance with management. The exact amount is not approved for external disclosure, even though it would help quantify the variance.', [('18,750 euros','FINANCIAL','PLACEHOLDER','essential')], ['The estimate assumes the planned shipment arrives in March; it does not include a possible refund.','The exact amount is not approved for external disclosure, even though it would help quantify the variance.'])]
records=[]; notes=[]
for slug,task,text,ents,facts in cases:
 id=f'{s}:{slug}'
 entities=[]; decisions=[]; out=text
 for i,(q,l,a,rel) in enumerate(ents,1):
  mid=f'm{i}'; eid=f'e{i}'
  entities.append(dict(id=mid,entity_id=eid,quote=q,label=l))
  d=dict(kind='entity',target_id=mid,entity_id=eid,quote=q,label=l,action=a,relevance=rel)
  if a=='PLACEHOLDER': d['reason']='The value is private or confidential and cannot be disclosed; '+('exact quantification is unavailable.' if rel=='essential' else 'the task can proceed without the exact value.')
  decisions.append(d)
  if a=='ALIAS': out=out.replace(q,'[PERSON_1]')
  elif a=='PLACEHOLDER': out=out.replace(q,f'[{l}]')
 rec=dict(schema_version=2,shard_id=s,id=id,family_id=f'{s}:{slug}-family',persona_id=f'{s}:{slug}-persona',source_id=f'{s}:{slug}-source',template_id=f'{s}:{slug}-template',split='dev',language='en',input_kind='message',task=task,text=text,entities=entities,decisions=decisions,required_facts=[{'quote':f} for f in facts],approved_output=out,provenance=dict(synthetic=True,human_audited=False,generator_id=f'{s}:generator',generator_model='gpt-6.1-terra'),review={'status':'pending'})
 records.append(rec)
 notes.append(dict(record_id=id,dependencies=[{'claim':f,'source_quotes':[f],'disclosable':True} for f in facts]+([{'claim':'Exact confidential shortfall','source_quotes':['18,750 euros'],'disclosable':False,'utility_limit':'Cannot calculate the numerical variance externally.'}] if slug=='finance' else [])))
(p/'draft-01.json').write_text(json.dumps(records,ensure_ascii=False,indent=2))
(p/'author-notes-01.jsonl').write_text(''.join(json.dumps(n,ensure_ascii=False)+'\n' for n in notes))
